// ─── Scraper: TikTok ─────────────────────────────────────────────────────────
// Actor: clockworks/free-tiktok-scraper

const config = $('Config').item.json;
const apifyToken = process.env.APIFY_TOKEN || '';

if (!apifyToken) {
  console.log('WARNING: APIFY_TOKEN no configurado');
  return [{ json: { _platform: 'tiktok', _error: 'APIFY_TOKEN no configurado', items: [] } }];
}

let items = [];
try {
  const results = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.apify.com/v2/acts/clockworks~free-tiktok-scraper/run-sync-get-dataset-items?token=${apifyToken}&timeout=120`,
    body: {
      hashtags: [config.keyword],
      resultsPerPage: config.maxAds || 30,
      maxItems: config.maxAds || 30
    },
    json: true,
    timeout: 180000
  });
  items = Array.isArray(results) ? results : [];
  console.log(`TikTok: ${items.length} videos obtenidos`);
} catch(e) {
  console.log('TikTok scrape error:', e.message);
}

return items.length > 0
  ? items.map(v => ({ json: v }))
  : [{ json: { _platform: 'tiktok', _empty: true } }];

// ─── Filtro de calidad: Facebook Ads ─────────────────────────────────────────
// La Ad Library NO tiene views ni duración. "Días activo" es el proxy de rendimiento.

const items = $input.all();
const config = $('Config').item.json;
const minDaysActive = config.minDaysActive || 7;
const maxAgeDays    = config.maxAgeDays || 90;
const filtered = [];

for (const item of items) {
  // Saltar items de error o vacíos
  if (item.json._empty || item.json._error) continue;

  const ad = item.json;
  const startDate = ad.startDate || ad.ad_delivery_start_time || ad.start_date || ad.adDeliveryStartTime;
  let daysActive = 0;

  if (startDate) {
    const start = new Date(startDate);
    const now   = new Date();
    daysActive  = Math.floor((now.getTime() - start.getTime()) / (1000 * 60 * 60 * 24));
  }

  if (daysActive >= minDaysActive && daysActive <= maxAgeDays) {
    const quality = daysActive >= 30 ? 'high' : daysActive >= 14 ? 'medium' : 'low';
    filtered.push({
      json: {
        ...ad,
        _daysActive:     daysActive,
        _platform:       'facebook',
        _qualitySignal:  quality,
        _adText:         ad.adText || ad.ad_creative_bodies?.[0] || ad.body || '',
        _adLink:         ad.adUrl || ad.ad_snapshot_url || '',
      }
    });
  }
}

filtered.sort((a, b) => (b.json._daysActive || 0) - (a.json._daysActive || 0));
const top = filtered.slice(0, 15);
console.log(`FB Ads filtrados: ${top.length}/${items.length}`);

return top.length > 0 ? top : [{ json: { _platform: 'facebook', _empty: true, _filtered: true } }];

// ─── Filtro de calidad: Instagram Ads ────────────────────────────────────────
// Misma lógica que Facebook — días activo como proxy.

const items = $input.all();
const config = $('Config').item.json;
const minDaysActive = config.minDaysActive || 7;
const maxAgeDays    = config.maxAgeDays || 90;
const filtered = [];

for (const item of items) {
  if (item.json._empty || item.json._error) continue;

  const ad = item.json;
  const startDate = ad.startDate || ad.ad_delivery_start_time || ad.start_date || ad.adDeliveryStartTime;
  let daysActive = 0;

  if (startDate) {
    const start = new Date(startDate);
    const now   = new Date();
    daysActive  = Math.floor((now.getTime() - start.getTime()) / (1000 * 60 * 60 * 24));
  }

  if (daysActive >= minDaysActive && daysActive <= maxAgeDays) {
    const quality = daysActive >= 30 ? 'high' : daysActive >= 14 ? 'medium' : 'low';
    filtered.push({
      json: {
        ...ad,
        _daysActive:     daysActive,
        _platform:       'instagram',
        _qualitySignal:  quality,
        _adText:         ad.adText || ad.ad_creative_bodies?.[0] || ad.body || '',
        _adLink:         ad.adUrl || ad.ad_snapshot_url || '',
      }
    });
  }
}

filtered.sort((a, b) => (b.json._daysActive || 0) - (a.json._daysActive || 0));
const top = filtered.slice(0, 15);
console.log(`IG Ads filtrados: ${top.length}/${items.length}`);

return top.length > 0 ? top : [{ json: { _platform: 'instagram', _empty: true, _filtered: true } }];

// ─── Filtro de calidad: TikTok ───────────────────────────────────────────────
// TikTok SÍ tiene views y duración real — aplicamos filtros estrictos.

const items = $input.all();
const config = $('Config').item.json;
const MIN_VIEWS    = config.minViews    || 100000;
const MIN_DURATION = config.minDuration || 15;
const MAX_AGE_DAYS = config.maxAgeDays  || 90;
const filtered = [];

for (const item of items) {
  if (item.json._empty || item.json._error) continue;

  const video = item.json;
  const views    = video.playCount || video.plays || video.viewCount || video.stats?.playCount || 0;
  const duration = video.duration  || video.videoLength || video.videoDuration || video.video?.duration || 0;
  const createTime = video.createTime || video.createdAt || video.publishedAt;

  let ageInDays = 0;
  if (createTime) {
    const created = new Date(typeof createTime === 'number' ? createTime * 1000 : createTime);
    ageInDays = Math.floor((new Date().getTime() - created.getTime()) / (1000 * 60 * 60 * 24));
  }

  if (views >= MIN_VIEWS && duration >= MIN_DURATION && ageInDays <= MAX_AGE_DAYS && ageInDays > 0) {
    const quality = views >= 1000000 ? 'high' : views >= 500000 ? 'medium' : 'low';
    filtered.push({
      json: {
        ...video,
        _views:          views,
        _duration:       duration,
        _ageInDays:      ageInDays,
        _platform:       'tiktok',
        _qualitySignal:  quality,
        _adText:         video.text || video.desc || video.description || '',
        _adLink:         video.webVideoUrl || video.shareUrl || '',
      }
    });
  }
}

filtered.sort((a, b) => (b.json._views || 0) - (a.json._views || 0));
const top = filtered.slice(0, 15);
console.log(`TikTok filtrados: ${top.length}/${items.length}`);

return top.length > 0 ? top : [{ json: { _platform: 'tiktok', _empty: true, _filtered: true } }];

// ─── Preparar Resumen ─────────────────────────────────────────────────────────
// Cuenta contenidos por plataforma, genera texto de resumen para Telegram,
// y pasa el payload completo al pipeline de modelado.

const items = $input.all();
const config = $('Config').item.json;

const summary = {
  facebook:  { total: 0, high: 0, medium: 0, low: 0 },
  instagram: { total: 0, high: 0, medium: 0, low: 0 },
  tiktok:    { total: 0, high: 0, medium: 0, low: 0 },
};

const validContents = [];

for (const item of items) {
  // Ignorar items de error/vacíos
  if (item.json._empty || item.json._error || item.json._filtered) continue;

  const platform = item.json._platform || 'unknown';
  const quality  = item.json._qualitySignal || 'low';

  if (summary[platform]) {
    summary[platform].total++;
    if (summary[platform][quality] !== undefined) summary[platform][quality]++;
  }

  validContents.push({
    platform,
    quality,
    text:      item.json._adText || '',
    link:      item.json._adLink || '',
    daysActive: item.json._daysActive || 0,
    views:      item.json._views || 0,
    raw:        item.json,
  });
}

const total = validContents.length;

const summaryText =
  `📊 *Contenidos encontrados para "${config.keyword}"*\n\n` +
  `• Facebook Ads: ${summary.facebook.total} (${summary.facebook.high} alta calidad)\n` +
  `• Instagram Ads: ${summary.instagram.total} (${summary.instagram.high} alta calidad)\n` +
  `• TikTok: ${summary.tiktok.total} (${summary.tiktok.high} alta calidad)\n\n` +
  `✅ *Total seleccionados para modelar: ${total}*\n` +
  `_Iniciando pipeline de modelado con tu DNA..._`;

console.log(`Resumen: ${total} contenidos válidos`);

return [{
  json: {
    contents:         validContents,
    summary,
    summaryText,
    totalContents:    total,
    keyword:          config.keyword,
    dna_expert:       config.dna_expert,
    dna_audience:     config.dna_audience,
    dna_product:      config.dna_product,
    telegram_chat_id: config.telegram_chat_id,
    email:            config.email,
  }
}];
